+// missingBareFields returns the names of bare output placeholders ({{.Name}})
+// that the data map will render as empty, and which of those sit inside an
+// href="" / src="" attribute. Deterministic and independent of "<no value>".
+// Names inside {{if .x}} / {{range .x}} are deliberately NOT reported: absence
+// there is correct gating, not a defect.
+var bareFieldRe = regexp.MustCompile(`\{\{\s*\.([A-Za-z_][A-Za-z0-9_]*)\s*\}\}`)
+
+func missingBareFields(tpl string, data map[string]interface{}) (missing, inURLAttr []string) {
+	seen := map[string]bool{}
+	for _, m := range bareFieldRe.FindAllStringSubmatchIndex(tpl, -1) {
+		name := tpl[m[2]:m[3]]
+		if seen[name] {
+			continue
+		}
+		v, present := data[name]
+		if present && v != nil && v != "" {
+			continue
+		}
+		seen[name] = true
+		missing = append(missing, name)
+		// attribute context: the 8 chars before the placeholder
+		if s := m[0] - 6; s >= 0 && (strings.HasSuffix(tpl[:m[0]], `href="`) || strings.HasSuffix(tpl[:m[0]], `src="`)) {
+			inURLAttr = append(inURLAttr, name)
+		}
+	}
+	sort.Strings(missing)
+	sort.Strings(inURLAttr)
+	return
+}
